python3 -c "from openpyxl import load_workbook; 
wb = load_workbook('gdp.xlsx'); 
task = wb['Task']; 

# Helper to get column letter
def col_l(c): return chr(64 + c)

# Step 1: Data retrieval
# Data years: 2018(H), 2019(I), 2020(J), 2021(K), 2022(L), 2023(M)
# Task years: 2019(H), 2020(I), 2021(J), 2022(K), 2023(L)
# Map Task Col to Data Col
col_map = {8: 'I', 9: 'J', 10: 'K', 11: 'L', 12: 'M'}

ranges = [(12, 17), (19, 24), (26, 31)]
for start_row, end_row in ranges:
    for r in range(start_row, end_row + 1):
        for c in range(8, 13):
            data_col = col_map[c]
            task.cell(row=r, column=c).value = f'=INDEX(Data!{data_col}5:{data_col}40, MATCH(D{r}, Data!B5:B40, 0))'

# Step 2: Net Exports % of GDP
for r in range(35, 41):
    r_idx = r - 35
    exp_r = 12 + r_idx
    imp_r = 19 + r_idx
    gdp_r = 26 + r_idx
    for c in range(8, 13):
        cl = col_l(c)
        task.cell(row=r, column=c).value = f'=({cl}{exp_r}-{cl}{imp_r})/{cl}{gdp_r}'

# Step 2: Stats
stats = [('MIN', 42), ('MAX', 43), ('MEDIAN', 44), ('AVERAGE', 45)]
for func, row_num in stats:
    for c in range(8, 13):
        cl = col_l(c)
        task.cell(row=row_num, column=c).value = f'={func}({cl}35:{cl}40)'

for c in range(8, 13):
    cl = col_l(c)
    task.cell(row=46, column=c).value = f'=PERCENTILE.INC({cl}35:{cl}40, 0.25)'
    task.cell(row=47, column=c).value = f'=PERCENTILE.INC({cl}35:{cl}40, 0.75)'

# Step 3: Weighted Mean
for c in range(8, 13):
    cl = col_l(c)
    task.cell(row=50, column=c).value = f'=SUMPRODUCT({cl}35:{cl}40, {cl}26:{cl}31)/SUM({cl}26:{cl}31)'

wb.save('gdp.xlsx')" && python3 /root/.gemini/skills/xlsx/recalc.py gdp.xlsx

